export const CRAFT_ATLASES={wood:{file:'craft-wood-atlas',cols:4,rows:2,count:7},water:{file:'craft-water-atlas',cols:4,rows:2,count:7},reed:{file:'craft-reed-atlas',cols:4,rows:2,count:7},dock:{file:'craft-dock-atlas',cols:4,rows:2,count:7},camp:{file:'craft-camp-scenes',cols:2,rows:2,count:4},river:{file:'craft-river-scenes',cols:3,rows:2,count:6},ruins:{file:'craft-ruins-atlas',cols:3,rows:2,count:6}};
const CRAFT_SCENES={roof:['camp',0],fire:['camp',1],path:['camp',2],home:['camp',3],spring:['river',0],stream:['river',1],reeds:['river',2],shore:['river',3],pier:['river',4],ferry:['river',5]};
const CRAFT_RUINS={shelter:0,hearth:1,path:2,spring:3,reeds:4,dock:5};
let craftSequence=0;
export const portraitAsset=who=>who==='mira'?'premium-mira':`craft-${who}`;
export function craftFrame(name){if(name.startsWith('mat-')){const[,chain,level]=name.split('-'),atlas=CRAFT_ATLASES[chain];if(!atlas||+level<1||+level>7)throw Error('Unknown material art');return{...atlas,index:+level-1};}if(name.startsWith('ruin-'))return{...CRAFT_ATLASES.ruins,index:CRAFT_RUINS[name.slice(5)]};const key=name.replace('scene-',''),entry=CRAFT_SCENES[key];if(!entry)throw Error('Unknown scenery art: '+name);return{...CRAFT_ATLASES[entry[0]],index:entry[1]};}
export function craftSvg(name,asset,{className='art-icon',x=0,y=0,width=64,height=64,id='',label='',padding=0}={}){const f=craftFrame(name),cx=(f.index%f.cols)*100,cy=Math.floor(f.index/f.cols)*100,pid=`craft-frame-${++craftSequence}`,size=100-padding*2;return`<svg ${id?`id="${id}"`:''} class="${className}" x="${x}" y="${y}" width="${width}" height="${height}" viewBox="0 0 100 100" overflow="hidden" ${label?`role="img" aria-label="${label}"`:'aria-hidden="true"'}><defs><pattern id="${pid}" x="${padding}" y="${padding}" width="${size}" height="${size}" patternUnits="userSpaceOnUse" viewBox="${cx} ${cy} 100 100" preserveAspectRatio="none"><image href="${asset(f.file)}" x="0" y="0" width="${f.cols*100}" height="${f.rows*100}" preserveAspectRatio="none"/></pattern></defs><rect x="${padding}" y="${padding}" width="${size}" height="${size}" fill="url(#${pid})"/></svg>`;}
export function createCraftElement(name,asset,className='art-icon'){const template=document.createElement('template');template.innerHTML=craftSvg(name,asset,{className});return template.content.firstElementChild;}
